#include <stdio.h>

int main(void)
{
    const int values[] = { 4, 7, 9, 12 };
    const size_t count = sizeof values / sizeof values[0];
    size_t i;
    int total = 0;

    for (i = 0; i < count; ++i) {
        total += values[i];
    }

    printf("count=%zu total=%d\n", count, total);
    return 0;
}
